def describe_autonomous_software_company() -> str:
    lines = [
        "TitanAI Autonomous Software Company Era",
        "",
        "This era extends TitanAI into a professional software company framework composed of specialized departments, operations, and company-level intelligence.",
        "",
    ]
    for capability in SOFTWARE_COMPANY_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
